  @{ Key = 'contrast-read'; Text = 'Select 2 other cards. Pass if every text and button is readable.' },
  @{ Key = 'contrast-off'; Text = 'Press Windows+U. Select Contrast themes. Choose None. Select Apply. Pass if the window returned to its colors.' },
  @{ Key = 'crumb'; Text = 'Open the card "FAKE OI 33-101". Pass if the line "Your Work > FAKE OI 33-101" reads as one line.' },
  @{ Key = 'status'; Text = 'On the same card: pass if the caption "ACTION STATUS" is level with the first line of the main card beside it.' },
  @{ Key = 'chip'; Text = 'On the same card, look at the format check. Pass if the label "Passed" is level with the text beside it.' },
  @{ Key = 'pubcol'; Text = 'Select All Actions in the list on the left. Pass if the publication titles, such as "Recall", start in one column.' },
  @{ Key = 'wheel'; Text = 'Put the pointer on the middle of the card "Your Work". Turn the mouse wheel. Pass if the card scrolls, or if the whole card shows with no scroll bar.' },
  @{ Key = 'pubnum'; Text = 'Select "All Actions". Pass if each publication number shows whole, with no dots.' }
)
# The cards, in the order the window builds them. A card: Rail (the rail item it lights), Title and Sub or Crumb and
# CrumbGo, Up (the card Esc opens), Side (the right column width at 100 %), Modal, and Cols: columns of sections, each
# section a list of Blocks (T = the block type; the window module builds each type).
$Cards = [ordered]@{}
$Cards.home = @{ Rail = 'work'; Title = 'Your Work'; Sub = "Tuesday, 17 Nov 26 $mid 2 items need you $mid 2 offices late"; Side = 300
  Cols = @(
    @(@{ Cap = 'Needs You Today'; Top = 'primary'; Blocks = @(@{ T = 'list'; Rows = @(
              @{ Chip = @('turn', 'Due 18 Nov 26'); Title = 'Review and start endorsement'; Sub = "FAKE OI 33-101, Key Control $mid step 8 of 12"
                Btn = @{ Text = 'Open'; Kind = 'primary'; Go = 'step8' } },
              @{ Chip = @('turn', 'Due 20 Nov 26'); Title = 'Build the final copy, then send for signatures'; Sub = "FAKE OI 21-14, Vehicle Keys $mid step 11 of 12"
                Btn = @{ Text = 'Open'; Go = 'step11' } },
              @{ Chip = @('late', '2 late'); Title = 'Chase 2 late offices'; Sub = "Wave answers past due $mid last contact shown on the right"
                Btn = @{ Text = 'Remind All Late'; Go = 'remindall' } }) }) },
      @{ Cap = "Who Has It Now $mid 15 open actions"; Grow = $true; Blocks = @(
          @{ T = 'p'; Text = "Since: when it reached that person $mid d: business days $mid dates in 2026"; Style = 'note' },
          @{ T = 'grid'; Name = 'Who has it now'; Rows = $GridHome; Cols = $ColsNarrow; ColsWide = $ColsWide; Fill = $true }) }),
    @(@{ Cap = "Chase $mid late and due soon"; Pad = 16; Blocks = @(
          @{ T = 'p'; Text = 'Each reminder is logged as a contact: the good-faith record (DAFMAN 90-161, 5.4.3.1).'; Style = 'note' },
          @{ T = 'list'; Narrow = $true; Rows = @(
              @{ Title = 'FAKE Office 5'; Sub = "FAKE Instruction 10-201 $mid Wave 1"; Detail = "Due 13 Nov 26 (2 days late) $mid last contact: 14 Nov 26 $mid contacts: 1"
                Btn = @{ Text = 'Remind'; Note = 'FAKE: a reminder to FAKE Office 5 is logged as a contact. Nothing was sent.' } },
              @{ Title = 'FAKE Office 8'; Sub = "FAKE OI 31-3 $mid Wave 2"; Detail = "Due 16 Nov 26 (1 day late) $mid last contact: never $mid contacts: 0"
                Btn = @{ Text = 'Remind'; Note = 'FAKE: a reminder to FAKE Office 8 is logged as a contact. Nothing was sent.' } },
              @{ Title = 'FAKE Legal Office'; Sub = "FAKE OI 90-1 $mid Wave 3, legal $mid cannot be ""Concur, No Response"""
                Detail = "Due 19 Nov 26 (due in 2 days) $mid last contact: never $mid contacts: 0"
                Btn = @{ Text = 'Remind'; Note = 'FAKE: a reminder to the FAKE Legal Office is logged as a contact. Nothing was sent.' } },
              @{ Title = 'FAKE Offices 2 and 4'; Sub = "FAKE OI 36-2 $mid Wave 1"; Detail = "Due 20 Nov 26 (due in 3 days) $mid last contact: never $mid contacts: 0"
                Btn = @{ Text = 'Remind'; Note = 'FAKE: a reminder to FAKE Offices 2 and 4 is logged as a contact. Nothing was sent.' } }) }) },
      @{ Cap = "Selected $mid FAKE Instruction 10-201"; Pad = 16; WideOnly = $true; Blocks = @(
          @{ T = 'rows'; Rows = @(@('Wave 1 (3 offices)', '2 of 3 answered', 'soon'), @('Wave 2 (5 mandatory)', 'Waiting', 'neu'),
              @('Wave 3, legal', 'Waiting', 'neu'), @('Contacts with FAKE Office 5', "1 $mid 14 Nov 26 0900", '')) },
          @{ T = 'buttons'; Items = @(@{ Text = 'Open the Action'; Go = 'waves' }, @{ Text = 'Change or Skip'; Go = 'step13' }) }) })) }
