# ---- File 23 of 39: T17\90161Z-T17-import-log-r3.ps1 (from scripts/gov/90161Z-T17-import-log-r3.ps1, sha256 4e49d30854bd)
$files += @{ Dir = 'T17'; Name = '90161Z-T17-import-log-r3.ps1'; Kind = 'text'; Sha = '4e49d30854bd'; Data = @'
<#
.SYNOPSIS
  90-161.Z Task 17 import log reader, r3 (R34: NOW lines and a tidier layout, same checks and output as r2;
  r2 was R20, PFM 14 Nov 26: r1 in R19 found an old log from an earlier round, so r2 reads only logs saved in the
  last 3 hours). Read-only. Windows PowerShell 5.1, no modules.
.DESCRIPTION
  What it is for: when a solution import fails, Power Automate offers "Download log file" (an Excel XML file). In R17 and
  R18 the error had to be pasted by hand and the paste held only the file's first lines. This script finds the newest
  import log and copies its error rows, so the next build sees the real error. About 1 minute (an estimate).
  It looks for the newest .xml file (changed in the last 3 hours) that is an Excel XML spreadsheet, in the T17 folder,
  Downloads, Desktop and Documents (local and OneDrive) and up to 2 folder levels below each (the browser saves where it
  saved last). From it, it writes T17\90161Z-T17-import-log-r3.txt (plain text): the column headings and every row that
  holds "fail", "error" or a 0x8 code, each cell joined with " | " (at most 80 rows). Every https address becomes <SITE>,
  every e-mail address <EMAIL> and the DODID <DODID>. No log found: one SKIP line (the import worked, or no log was
  downloaded). It changes nothing else.
  Output: the file above (the round collects it) and lines that start with ITEM. Lines that start with NOW say what
  the script is doing; they are not results.
  Network: none.
  Writes: 90161Z-T17-import-log-r3.txt in the T17 folder (the folder is made when missing).
  Credentials: none.
  Parameters (used by RADE): -Id, -NoPause.
#>
param([string]$Id, [switch]$NoPause)
$task = 'T17'
$ErrorActionPreference = 'Stop'

# @@SHARED task-common-a5c2aafc@@ (RADE writes the shared block "task-common" here; its text is in the bundle part "Shared blocks")

function Hide-Export([string]$Text, [string[]]$Secret) {
  # Masks the DODID, every https address, every e-mail address and bare SharePoint-type host names in $Text.
  $t = ConvertTo-Masked $Text $Secret
  $t = $t -replace 'https?://[^\s"''<>]+', '<SITE>'
  $t = $t -replace '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}', '<EMAIL>'
  $t = $t -replace '\b[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.(sharepoint|dynamics|crm|powerapps|appsplatform)[A-Za-z0-9.-]*', '<HOST>'   # bare host names
  return $t
}

function Test-ExcelXml([string]$Path) {
  # An Excel XML spreadsheet names its namespace in the first few KB.
  try {
    $sr = New-Object System.IO.StreamReader($Path)
    try { $buf = New-Object char[] 4096; $n = $sr.Read($buf, 0, 4096); $head = New-Object string($buf, 0, $n) } finally { $sr.Dispose() }
    return ($head -match 'urn:schemas-microsoft-com:office:spreadsheet')
  } catch { return $false }
}

$code = 0
try {
  $who = Get-TaskId $Id
  $dir = Get-TaskDir $who.Id $task 'T17' -Create
  $places = @($dir)
  $homes = @()
  if ($env:USERPROFILE) { $homes += $env:USERPROFILE }
  $homes += (Join-Path (Join-Path 'C:\Users' $who.Id) 'OneDrive - United States Air Force')
  if ($env:OneDrive) { $homes += $env:OneDrive }
  foreach ($hm in ($homes | Select-Object -Unique)) { foreach ($sub in @('Downloads', 'Desktop', 'Documents')) { $places += (Join-Path $hm $sub) } }
  $since = (Get-Date).AddHours(-3)   # r2: this round only (R19 found an old log)
  $log = $null
  Write-Output 'NOW Looking for an import log saved in the last 3 hours.'
  foreach ($pl in ($places | Select-Object -Unique)) {   # the newest log wins, wherever it is (each folder and 2 levels below it)
    if (-not (Test-Path -LiteralPath $pl -PathType Container)) { continue }
    $found = Get-ChildItem -LiteralPath $pl -Filter '*.xml' -File -Recurse -Depth 2 -ErrorAction SilentlyContinue
    foreach ($f in @($found | Where-Object { $_.LastWriteTime -gt $since } | Sort-Object LastWriteTime -Descending)) {
      if ($log -and $f.LastWriteTime -le $log.LastWriteTime) { break }
      if (Test-ExcelXml $f.FullName) { $log = $f; break }
    }
  }
  if (-not $log) {
    Write-Output 'ITEM import-log SKIP no Excel XML import log from the last 3 hours in T17, Downloads, Desktop or Documents (the import worked, or no log was downloaded)'
  } else {
    Write-Output 'NOW Reading the import log and picking its error rows.'
    $doc = New-Object System.Xml.XmlDocument
    $doc.XmlResolver = $null
    $doc.Load($log.FullName)
    $out = New-Object System.Collections.Generic.List[string]
    $out.Add('IMPORT LOG ' + (Hide-Export $log.Name $who.Secret) + ', saved ' + $log.LastWriteTime.ToString('yyyy-MM-dd HH:mm'))
    $kept = 0; $rows = 0; $full = $false
    foreach ($ws in @($doc.SelectNodes("//*[local-name()='Worksheet']"))) {
      $wsName = ''; foreach ($a in $ws.Attributes) { if ($a.LocalName -eq 'Name') { $wsName = $a.Value } }
      $out.Add('SHEET ' + (Hide-Export $wsName $who.Secret))
      if ($full) { break }   # at most 80 rows in all
      $first = $true
      foreach ($row in @($ws.SelectNodes(".//*[local-name()='Row']"))) {
        $rows++
        $cells = @($row.SelectNodes("./*[local-name()='Cell']") | ForEach-Object { ([string]$_.InnerText).Trim() -replace '\s+', ' ' })
        $text = ($cells -join ' | ')
        if ($first -or $text -match '(?i)fail|error|0x8') {
          if ($kept -ge 80) { $full = $true; break }
          if ($text.Length -gt 600) { $text = $text.Substring(0, 600) + ' ...' }
          $out.Add((Hide-Export $text $who.Secret)); $kept++
        }
        $first = $false
      }
    }
    $file = Join-Path $dir '90161Z-T17-import-log-r3.txt'
    Write-Output 'NOW Saving the error rows to the T17 folder.'
    Set-Content -LiteralPath $file -Value $out -Encoding UTF8
    Write-Output ('ITEM import-log PASS rows=' + $rows + ' kept=' + $kept + ' copied to T17\90161Z-T17-import-log-r3.txt (addresses masked)')
  }
} catch {
  $sec = @(); if ($who -and $who.Secret) { $sec = $who.Secret }
  $msg = Hide-Export ([string]$_.Exception.Message) $sec; if ($msg.Length -gt 160) { $msg = $msg.Substring(0, 160) }   # mask first, then cut
  Write-Output ('ITEM import-log FAIL ' + $msg)
  $code = 1
}
if (-not $NoPause) { [void](Read-Host 'Press Enter to close') }
exit $code
'@ }
# ---- File 24 of 39: T21\90161Z-T21-probe-r10.ps1 (from scripts/gov/90161Z-T21-probe-r10.ps1, sha256 fc3e24a93ca1)
$files += @{ Dir = 'T21'; Name = '90161Z-T21-probe-r10.ps1'; Kind = 'text'; Sha = 'fc3e24a93ca1'; Data = @'
<#
.SYNOPSIS
  90-161.Z Task 21 probe, r10 (round R36). Windows PowerShell 5.1, the installed PnP.PowerShell 1.12.0 (no other module).
.DESCRIPTION
  What it is for: the device side of the T21 probe. R26 settled most of the front-end tests (T2, T3, T5, T6, T7, T9, T10
  passed); R29a proved T4 (a second person writes a row). The 2 probe flows are now flows of the solution "90-161.Z flows"
  (fallback A, the PFM 18 Nov 26: a new solution and a hand-made flow failed in R29a to R32 with "The connections could
  not be loaded"; an upgrade of that solution works): "90161Z T21 Probe Health r6" answers a command row with a result row,
  and "90161Z T21 Probe Button r6" is started by a list view button. Excel is not repeated (R27: no Automate tab).
  This script makes the list and library the tests need, adds the second person to the site's Visitors group (and removes
  the person again), formats the list form and a view, starts the health flow, reads what the people and the flows wrote,
  and removes everything it made. Fake data only (the fake workbook comes from scripts/build_probe_samples.py). Counts,
  status codes and field names only: no names, addresses or text from the tenant.
  WHAT R10 CHANGES (R36; R35 finding 3): the new part Ask writes T4Asked=yes into the person state file and puts the new
  row form link on the clipboard, before the second person adds a row titled T4a; Read (module read r10) counts T4 only
  then, or when a row by another person is there. The whole set is r10, so the probe loads one revision.
  WHAT R8 CHANGED (PFM 19 Nov 26, F2 B): the new part Office and the test EDITALL prove that a PFM Office member who is not
  a row's author can edit that row on a list set to "edit own rows" (the level T20 r2 gives the group PFM Office, F2 A).
  The part lives in the new module "office"; Read prints the EDITALL line, Clean also takes the person out of PFM Office.
  WHAT R7 CHANGED: (1) the health flow writes its row without the Power Automate Management connector, so HEALTH now tests
  that the flow ran on the SharePoint connection of the solution (it no longer counts flows). (2) View takes the button
  flow's ID from the button-flow-id block of the look module, which scripts/build_flow_solution.py writes at build time
  (the ID is the same on every build); the Export part, its module and the flow ID file are gone. (3) BUTTON counts the
  rows titled BTN-FLOW that the button flow writes. (4) Before each action that takes time a part prints one line
  "NOW <what it does>" for the RADE window; a NOW line is not a result line and is not in the result file.
  WHAT R6 CHANGED: (1) the Clean part no longer prints the Recycle Bin item IDs of the list and the library (R29a finding 7:
  a raw RecycleBinItemId table reached the log). (2) The parts Form and View run the two halves of Look on their own, so the
  round can show the list form when the form header passed, whatever the view result (R29a finding 6); Look still runs both.
  (3) The script is split into modules (code standard, S1): this file holds the start, the shared blocks and the result
  file; the parts live in the files 90161Z-T21-<part>-r10.ps1 in the same folder, which this file loads by name.
  (4) Read: with no state file and no row by another person, T4 is not counted: one line "T4 NOT RUN" and no RESULT line.
  Parts (-Part):
    Make   (about 1 minute, an estimate)  Makes the library "90161Z Probe Files" and the list "90161Z Probe" (columns
           ProbeTest, ProbeWay, ProbeResult, ProbeDetail; its own permissions: the site's copied, then Contribute for the
           site's Visitors group on this list only), saves the fake workbook from a text block in the make module, uploads
           it and writes the test page 90161Z-T21-links-r5.html (4 links). Run it twice and the second run changes nothing.
    Person (about 1 minute, an estimate)  Opens a small window and asks for the e-mail address of the second person (test
           T4). The address stays in memory: it is never written to a file, to the screen or to the results. With your own
           sign-in it adds that person to the site's Visitors group and saves only the number of the site user (no address,
           no name) in the state file 90161Z-T21-person-state-r3.txt in the T21 folder, so that Clean can find the person.
           It also puts the link of the new row form on the clipboard. Prints "added to Visitors: yes" or "no" and a status.
    Office (about 1 minute, an estimate; after Person and after T20 r2)  Sets "edit own rows" on the probe list, gives
           the group PFM Office the level "PFM Office Edit All Items" on it, writes 1 row titled EDITALL (you are its
           author), puts the second person of Person into PFM Office (state file 90161Z-T21-office-state-r8.txt: numbers
           only) and reads back that the person can edit every row. The row's edit form link goes on the clipboard: the
           second person opens it, changes the row and saves it.
    Ask    (a few seconds; no sign-in; after Person)  Writes T4Asked=yes into the state file 90161Z-T21-person-state-r3.txt
           and puts the link of the new row form on the clipboard, for the second person's row T4a.
    Run    (a few seconds, an estimate)  Adds 1 command row (RUN-HEALTH) that starts the health flow "90161Z T21 Probe
           Health r6"; it answers within minutes.
    Look   (about 1 minute, an estimate)  Runs Form, then View.
    Form   (about 1 minute, an estimate)  Sets a header on the list form (the content type's form formatting) and reads it back.
    View   (about 1 minute, an estimate)  Makes the view "ProbeButton" with a button that starts the button flow "90161Z
           T21 Probe Button r6" (a view formatting with the action executeFlow; the flow's ID is in the look module).
    Open   (a few seconds; no sign-in)  Writes the test page again and opens it in the browser.
    Read   (about 1 to 5 minutes, an estimate)  Waits up to -WaitMinutes (default 4) for the health flow's row, then prints
           one line each for HEALTH, T4, EDITALL and BUTTON (counts only; the button flow's rows are the ones titled
           BTN-FLOW). EDITALL passes when the second person saved the EDITALL row that you wrote.
    Clean  (about 1 minute, an estimate)  Removes the second person from the Visitors group and from PFM Office again (found
           by the saved numbers; then deletes the state files), then moves the list and the library to the site Recycle Bin (restorable
           for 93 days). Each step runs even if an earlier one failed, and the part can be run again. The 2 probe flows
           stay in the solution "90-161.Z flows" (the part says so). The round runs it twice: first (-Label first), last
           (-Label last).
  WHAT IT CHANGES ON THE SITE: Make adds the two objects, their columns, their permissions and two files. Person adds one
  person to the Visitors group. Office sets "edit own rows" and the PFM Office level on the probe list, adds 1 row and puts
  that person into PFM Office. Run adds 1 row. Form sets one form formatting; View adds one view. Read, Open and Ask change
  nothing on the site. Clean undoes Person and recycles the two objects. On this computer: the T21 folder (the test
  page, the state file). Every output line shows the site as <SITE> and the DODID as <DODID>; the test page holds the
  site address and stays on this computer (it is not a result file).
  Network: the one SharePoint site given in RADE (RADE_SITE) or in Config\90161Z-site.txt, through PnP.PowerShell; Open
           and Ask use no network (Open hands the test page to the browser).
  Writes: the site objects listed above; on this computer the T21 folder (result files, test page, state files, the fake
          workbook) and, once, Config\90161Z-site.txt when the site address is typed outside RADE.
  Credentials: your own CAC sign-in through the PnP web login window (Connect-PnPOnline -UseWebLogin); nothing is stored.
  Output: 90161Z-T21-probe-<part>-r10.txt (make, person, office, run, look, form, view, read) or -clean-<label>-r10.txt in
  the T21 folder (send them back). Each test line (HEALTH, T4, EDITALL, BUTTON, FORM, VIEW) is followed by "RESULT <test> PASS" or
  "RESULT <test> FAIL", so the RADE step counts what the part read (R28 finding 7). Last line of each part: PROBE <part>
  done: passed=<n> failed=<n>. Exit code 0 when the part ran to its end (a FAILED test is a result); exit 1 only when the
  part could not run (sign-in, missing list, missing module file).
  Run: powershell.exe -NoProfile -ExecutionPolicy Bypass -File 90161Z-T21-probe-r10.ps1 -Part <part> (RADE does this).
  Parameters (used by RADE, the Redacted Application Deployment Engine): -Id, -Part, -Label, -WaitMinutes, -NoPause.
  -PollSeconds, -TestDir and -NoLaunch are for the tests in tests/run.sh (tests/ps/Test-T21.ps1).
.PARAMETER Id
  The DODID (the profile folder name); empty = the profile folder of this computer.
.PARAMETER Part
  The part to run: Make, Person, Ask, Office, Run, Look, Form, View, Open, Read or Clean.
.PARAMETER Label
  For Clean: first or last (it goes into the result file name).
.PARAMETER WaitMinutes
  How long Read waits for the health flow's row (default 4 for Read).
.PARAMETER NoPause
  No "Press Enter to close" at the end.
.PARAMETER PollSeconds
  Seconds between two checks while Read waits (tests use 1).
.PARAMETER TestDir
  Test runs only: the folder to use instead of the T21 folder.
.PARAMETER NoLaunch
  Test runs only: do not open the browser or use the clipboard.
#>
param([string]$Id, [ValidateSet('Make', 'Person', 'Ask', 'Office', 'Run', 'Look', 'Form', 'View', 'Open', 'Read', 'Clean')][string]$Part,
  [ValidateSet('', 'first', 'last')][string]$Label = '', [double]$WaitMinutes = 14, [switch]$NoPause, [int]$PollSeconds = 20,
  [string]$TestDir, [switch]$NoLaunch)
$task = 'T21'
$script:pollEvery = $PollSeconds
$script:LibTitle = '90161Z Probe Files'
$script:LibFolder = '90161ZProbeFiles'
$script:ListTitle = '90161Z Probe'
$script:ListFolder = '90161ZProbe'
$script:BookName = '90161Z-T21-fake-book-r1.xlsx'
# The test page keeps its r5 name: the round's sample page (samples/90161Z-T21-links-r5.html) has that name, and no check
# ties it to the script revision.
$script:LinksName = '90161Z-T21-links-r5.html'
# The state file keeps its r3 name: Clean finds a person that an earlier round added through it.
$script:StateName = '90161Z-T21-person-state-r3.txt'
# The part Office (F2 B): the group and the level T20 r2 makes (the same names as there; tests/ps/Test-T21.ps1 checks), and
# its own state file for Clean.
$script:OfficeGroup = 'PFM Office'
$script:OfficeLevel = 'PFM Office Edit All Items'
$script:OfficeStateName = '90161Z-T21-office-state-r8.txt'   # keeps r8: same format, so a person an r8 run left is found
$script:ViewTitle = 'ProbeButton'
$script:HeaderText = '90-161.Z test header'
$Rev = 'r10'
# The modules this file loads from its own folder (round skill section 2: scripts that load each other keep fixed names).
$ModuleNames = @('common', 'make', 'person', 'office', 'look', 'read')

# @@SHARED task-common-a5c2aafc@@ (RADE writes the shared block "task-common" here; its text is in the bundle part "Shared blocks")
# @@SHARED site-common-cc1bf548@@ (RADE writes the shared block "site-common" here; its text is in the bundle part "Shared blocks")

$secret = @()
$site = ''
$lines = New-Object System.Collections.Generic.List[string]
$dir = ''
$passed = 0; $failed = 0
$fatal = $false
$script:fmtError = ''
try {
  $ErrorActionPreference = 'Stop'
  if (-not $Part) { throw 'PART not given: use -Part Make, Person, Ask, Office, Run, Look, Form, View, Open, Read or Clean.' }
  # The modules are dot-sourced here, in this script's scope, so their functions see the values above.
  foreach ($moduleName in $ModuleNames) {
    $moduleFile = Join-Path $PSScriptRoot ('90161Z-T21-' + $moduleName + '-' + $Rev + '.ps1')
    if (-not (Test-Path -LiteralPath $moduleFile -PathType Leaf)) {
      throw ('MODULE missing: 90161Z-T21-' + $moduleName + '-' + $Rev + '.ps1 is not in the folder of this script. Run the round again.')
    }
    . $moduleFile
  }
  if ($Part -eq 'Read' -and -not $PSBoundParameters.ContainsKey('WaitMinutes')) { $WaitMinutes = 4 }
  $who = Get-TaskId $Id
  $id = $who.Id
  $secret = $who.Secret
  if ($TestDir) { $dir = $TestDir } else { $dir = Get-TaskDir $id $task 'Task 21' -Create }
  Set-Location -LiteralPath $dir
  $configDir = Join-Path (Split-Path -Parent $dir) 'Config'
  $site = Get-SiteAddress $configDir
  $lines.Add('TASK T21 probe ' + $Rev + ', part ' + $Part + ', ' + (Get-Date -Format 'yyyy-MM-dd HH:mm') + $(if ($Part -eq 'Read') { ', wait-minutes=' + $WaitMinutes } else { '' }))

  # Open and Ask work on this computer only; every other part signs in first.
  if ($Part -eq 'Open') { Invoke-OpenPart } elseif ($Part -eq 'Ask') { Invoke-AskPart }
  else {
    Connect-ProbeSite
    switch ($Part) {
      'Make' { Invoke-MakePart }
      'Person' { Invoke-PersonPart }
      'Office' { Invoke-OfficePart }
      'Run' { Invoke-RunPart }
      'Look' { Invoke-FormPart; Invoke-ViewPart }
      'Form' { Invoke-FormPart }
      'View' { Invoke-ViewPart }
      'Read' { Invoke-ReadPart }
      default { Invoke-CleanPart }
    }
    try { $null = & { Disconnect-PnPOnline -ErrorAction SilentlyContinue } *>&1 } catch { $null = $_ }
  }
  $lines.Add('PROBE ' + $Part + ' done: passed=' + $passed + ' failed=' + $failed)
} catch {
  $fatal = $true
  $m = ConvertTo-Masked (Hide-Site ([string]$_) $site) $secret
  $lines.Add('STOPPED: ' + $m.Substring(0, [Math]::Min(400, $m.Length)) + ' (a part that stopped can be run again: Make skips what is there, Clean finishes what is left)')
  $lines.Add('PROBE ' + $Part + ' done: passed=' + $passed + ' failed=' + $failed)
} finally {
  # Every line is masked once more before it is shown or saved; Open writes no result file.
  $masked = @($lines | ForEach-Object { ConvertTo-Masked (Hide-Site $_ $site) $secret })
  $resultName = '90161Z-T21-probe-' + ([string]$Part).ToLowerInvariant() + $(if ($Label) { '-' + $Label } else { '' }) + '-' + $Rev + '.txt'
  if ($dir -and $Part -and $Part -ne 'Open') { try { Set-Content -LiteralPath (Join-Path $dir $resultName) -Value $masked -Encoding UTF8 } catch { $null = $_ } }
  $masked | ForEach-Object { Write-Host $_ }
  if (-not $NoPause -and -not $env:RADE_CONTRACT) { [void](Read-Host 'Press Enter to close') }
}
if ($fatal) { exit 1 }
exit 0
'@ }
# ---- File 25 of 39: T21\90161Z-T21-common-r10.ps1 (from scripts/gov/90161Z-T21-common-r10.ps1, sha256 fdcce3d6c84c)
$files += @{ Dir = 'T21'; Name = '90161Z-T21-common-r10.ps1'; Kind = 'text'; Sha = 'fdcce3d6c84c'; Data = @'
<#
.SYNOPSIS
  90-161.Z Task 21 probe r10, module "common": the helpers every part of the probe uses.
.DESCRIPTION
  Loaded by 90161Z-T21-probe-r10.ps1 (dot-sourced from the same folder); it does nothing when it is run alone.
  Inputs: the values the main file sets in its own scope ($site, $dir, $lines, $passed, $failed, $WaitMinutes, $pollEvery,
  $StateName). Outputs: functions for the SharePoint REST calls, the result lines, the NOW lines, the wait loop, the
  second person's saved numbers and the sign-in.
  Network: the one SharePoint site of the main file ($site), through the PnP.PowerShell connection.
  Writes: none on the site by itself (Invoke-Rest sends what a part asks for); the result lines in memory.
  Credentials: your own CAC sign-in through the PnP web login window (Connect-ProbeSite); nothing is stored.
  Run: not alone; powershell.exe -File 90161Z-T21-probe-r10.ps1 -Part <part> loads it.
#>

<#
.SYNOPSIS
  Sends one SharePoint REST request through the signed-in PnP connection (the same call T20 uses).
.PARAMETER Method
  Get, Post or Merge.
.PARAMETER Uri
  The address after the site, for example _api/web/lists.
.PARAMETER Body
  The JSON body for Post and Merge (verbose form); empty for Get.
.OUTPUTS
  System.String. The raw answer text.
#>
function Invoke-Rest([string]$Method, [string]$Uri, [string]$Body) {
  $url = $script:site.TrimEnd('/') + '/' + $Uri
  if ($Method -eq 'Get') { return [string](Invoke-PnPSPRestMethod -Method Get -Url $url -Raw -ErrorAction Stop) }
  return [string](Invoke-PnPSPRestMethod -Method $Method -Url $url -Content $Body -ContentType 'application/json;odata=verbose' -Raw -ErrorAction Stop)
}
# Reads a REST collection and returns its "value" items as an array.
function Get-RestValue([string]$Uri) { return @(((Invoke-Rest 'Get' $Uri '') | ConvertFrom-Json).value) }
function Get-SiteList {
  # Every list on the site that is not hidden, with the folder name it was made under (the folder name never changes).
  $select = '$select=Id,Title,ItemCount,BaseTemplate,Hidden,EnableAttachments,HasUniqueRoleAssignments,RootFolder/Name'
  return @(Get-RestValue ('_api/web/lists?' + $select + '&$expand=RootFolder&$top=1000') | Where-Object { -not $_.Hidden })
}
# Finds a list or library by the folder name it was made under; returns it, or $null.
function Find-ByFolder([string]$Folder) {
  foreach ($l in (Get-SiteList)) { if ([string]$l.RootFolder.Name -eq $Folder) { return $l } }
  return $null
}
# Prints one "NOW <text>" line before an action that takes time (the RADE window shows it as it happens). It goes to the
# screen only: it is not a result line, so it is not added to the result lines or the result file and is not counted.
function Write-Now([string]$Text) { Write-Host ('NOW ' + $Text) }
# Adds one "ITEM <name> <status> <text>" line and counts a PASS or a FAIL.
function Add-Item([string]$Name, [string]$Status, [string]$Text) {
  $script:lines.Add('ITEM ' + $Name + ' ' + $Status + $(if ($Text) { ' ' + $Text } else { '' }))
  if ($Status -eq 'PASS') { $script:passed++ } elseif ($Status -eq 'FAIL') { $script:failed++ }
}
function Add-Test([string]$Name, [string[]]$Piece, [bool]$Pass) {
  # One summary line per test: "T4 PASSED: a ...; next ...".
  $script:lines.Add($Name + ' ' + $(if ($Pass) { 'PASSED' } else { 'FAILED' }) + ': ' + ($Piece -join '; '))
  # The runner counts a line as passed or failed only by the separate word PASS or FAIL (R28 finding 7: this part read PASSED
  # while its 3 tests failed), so each test also gets one RESULT line.
  $script:lines.Add('RESULT ' + $Name + ' ' + $(if ($Pass) { 'PASS' } else { 'FAIL' }))
  if ($Pass) { $script:passed++ } else { $script:failed++ }
}
function Format-Detail([string]$Text) {
  # The flow's ProbeDetail (or an error text) for a line: one line, anything that looks like an address or a link masked, cut to 160.
  $t = ($Text -replace '\s+', ' ').Trim()
  $t = $t -replace '[^\s"<>|,;()\[\]]+@[^\s"<>|,;()\[\]]+', '<MASKED>'
  $t = $t -replace '[^\s"<>|,;()\[\]]+%40[^\s"<>|,;()\[\]]+', '<MASKED>'
  $t = $t -replace 'https?://\S+', '<MASKED>'
  if ($t.Length -gt 160) { $t = $t.Substring(0, 160) }
  return $t
}
function Get-ListRow([string]$Title, [string[]]$Fields) {
  # Plain rows (Id and the named fields as text); only counts and flags are written from them.
  $rows = @(Get-PnPListItem -List $Title -Fields $Fields -PageSize 500 -ErrorAction Stop)
  return @($rows | ForEach-Object {
    $o = @{ Id = [int]$_.Id; Item = $_ }
    foreach ($f in $Fields) { $o[$f] = [string]$_[$f] }
    $o
  })
}
function Find-Result($Rows, [string]$Test, [string]$Way) {
  # The newest RESULT row for a test and way, or $null.
  $hit = @($Rows | Where-Object { $_.Title -eq 'RESULT' -and $_.ProbeTest -eq $Test -and $_.ProbeWay -eq $Way } | Sort-Object { $_.Id } -Descending)
  if ($hit.Count) { return $hit[0] }
  return $null
}

<#
.SYNOPSIS
  Checks every $pollEvery seconds for up to $WaitMinutes (both set by the main file); a NOW line a minute.
.DESCRIPTION
  A failed check is retried; 3 failures in a row stop the part (the error goes to the caller). This one differs from the
  shared Wait-Until of T18 and T24 (scripts/gov/src/wait-common.ps1): it takes its poll time from -PollSeconds, so the tests
  can wait 1 second, and it prints one NOW line a minute.
.PARAMETER Done
  The check: a script block that returns $true when the wait is over.
.PARAMETER What
  What is waited for, for the progress line.
.OUTPUTS
  System.Boolean. $true when the check passed in time, $false when the time ran out.
#>
function Wait-Until([scriptblock]$Done, [string]$What) {
  $start = Get-Date
  $end = $start.AddMinutes($WaitMinutes)
  $misses = 0; $nextNote = $start.AddMinutes(1)
  while ($true) {
    $isDone = $false
    try { $isDone = [bool](& $Done); $misses = 0 }
    catch {
      $misses++
      if ($misses -ge 3) { throw }
      Write-Now ('Checking again (a check failed, ' + $misses + ' of 3 allowed in a row)')
    }
    if ($isDone) { return $true }
    $now = Get-Date
    if ($now -ge $end) { return $false }
    if ($now -ge $nextNote) {
      Write-Now ('Waiting for ' + $What + ' (' + [int]($now - $start).TotalMinutes + ' of ' + $WaitMinutes + ' minutes)')
      $nextNote = $nextNote.AddMinutes(1)
    }
    Start-Sleep -Seconds $pollEvery
  }
}
# The site user number of the author of a row, or 0 when the row has none.
function Get-AuthorId($Row) { $a = $Row.Item['Author']; if ($a -and $a.LookupId) { return [int]$a.LookupId }; return 0 }
# The site user number of the person who saved a row last (Modified By), or 0 when the row has none.
function Get-EditorId($Row) { $a = $Row.Item['Editor']; if ($a -and $a.LookupId) { return [int]$a.LookupId }; return 0 }
# The site user numbers of the members of one site group.
function Get-GroupMemberId([int]$GroupId) {
  return @(Get-RestValue ('_api/web/sitegroups/getbyid(' + $GroupId + ')/users?$select=Id&$top=5000') | ForEach-Object { [int]$_.Id })
}
# The Id of the site's associated Visitors group, or 0 when the site has none or it cannot be read.
function Get-VisitorGroupId {
  try { return [int]((Invoke-Rest 'Get' '_api/web/associatedvisitorgroup?$select=Id' '') | ConvertFrom-Json).Id } catch { return 0 }
}
function Read-State([string]$Dir) {
  # The saved numbers of the second person (site user Id, group Id, whether the person was a member before): no address, no name.
  $f = Join-Path $Dir $StateName
  if (-not (Test-Path -LiteralPath $f -PathType Leaf)) { return $null }
  $h = @{}
  foreach ($l in @(Get-Content -LiteralPath $f)) { if ([string]$l -match '^(\w+)=(.*)$') { $h[$Matches[1]] = $Matches[2].Trim() } }
  if ($h['UserId'] -notmatch '^\d+$') { return $null }
  return $h
}
<#
.SYNOPSIS
  Loads PnP.PowerShell, signs in to the site with the web login (CAC) and reads the lists once, so the REST route is
  proved by a read before anything is written. Adds the lines ROUTE and ITEM a-rest-read.
#>
function Connect-ProbeSite {
  Write-Now 'Loading PnP.PowerShell'
  $mod = @(Get-Module -ListAvailable -Name PnP.PowerShell | Sort-Object Version -Descending)
  if (-not $mod.Count) { throw 'PNP not installed: PnP.PowerShell is not on this computer.' }
  $null = & { Import-Module PnP.PowerShell -RequiredVersion $mod[0].Version -DisableNameChecking } *>&1
  Write-Now 'Signing in to the site (if a sign-in window opens, sign in with your CAC)'
  $null = & { Connect-PnPOnline -Url $script:site -UseWebLogin -ErrorAction Stop } *>&1
  $script:lines.Add('ROUTE web-login PASS')
  Write-Now 'Reading the lists of the site'
  $siteLists = Get-SiteList
  $script:lines.Add('ITEM a-rest-read INFO lists read from the site=' + $siteLists.Count)
}
'@ }
