$steps += @{ Name = 'T22 Open the 90-161.Z window r10'; Title = 'Open the 90-161.Z window and do its 18 checks'; Dir = 'T22'; File = '90161Z-T22-pfm-window-r10.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'Opens your 90-161.Z window with fake data and saves a picture of each card. Do the 18 checks in the bar at the bottom. Feedback in the bar saves a comment on a card.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 900; DoneText = ''; DoneLog = ''; Makes = @(); After = @(); Optional = $false; Help = 'Send the results as they are. The step can be run again.'; Doing = 'Opening the 90-161.Z window.' }
$steps += @{ Name = 'T22 Did the window open r10'; Title = 'Check that the window opened'; Dir = 'T22'; File = '90161Z-T22-pfm-window-r10.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 2; Args = '-Opened'; Note = 'Reads the result of the window step and opens nothing. Passes when the window opened, so the look questions run even when a check failed.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 60; DoneText = ''; DoneLog = ''; Makes = @(); After = @(); Optional = $false; Help = 'Send the results as they are.'; Doing = 'Reading the result of the window step.' }
$steps += @{ Name = 'T22 Answer: look and cards r10'; Title = 'Answer 3 questions about the window look'; Dir = 'T22'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = '3 questions about the look of the window. About 2 minutes.'; Kind = 'guide'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 120; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T22 Did the window open r10'); Optional = $false; Help = ''; AnswersOnly = $true; Answers = @(@{ Key = 'w-look'; Prompt = 'Does the window look like your vision of the 90-161.Z app?'; Kind = 'pick'; Choices = @('Yes, as it is', 'Close, with small changes', 'Partly', 'No') }, @{ Key = 'w-cards'; Prompt = 'Did every card open and fit with no scroll bar?'; Kind = 'yesno'; Choices = @() }, @{ Key = 'w-change'; Prompt = 'What would you change first? One line, no names.'; Kind = 'text'; Choices = @() }) }
$steps += @{ Name = 'T01 Render the sample publication r10'; Title = 'Make the sample publication in Word'; Dir = 'T01'; File = '90161Z-T01-renderer-test-r10.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'Checks the fake sample publication, then makes it in Word twice (draft, then final with a PDF). Word works in the background; it can take a few minutes.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 240; DoneText = ''; DoneLog = ''; Makes = @(); After = @(); Optional = $false; Help = 'Send the results as they are. The step can be run again.'; Doing = 'Making the sample publication in Word.' }
$steps += @{ Name = 'T07 Render the sample with 2 test seals r6'; Title = 'Make the sample publication with 2 test seals'; Dir = 'T07'; File = '90161Z-T07-seal-test-r6.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'Prepares 4 fake test seals, then makes the fake sample publication twice in Word with a seal on the cover (a tall one, then a round one), each with a PDF.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 240; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T01 Render the sample publication r10'); Optional = $false; Help = 'Send the results as they are. The step can be run again.'; Doing = 'Making the sample publication with the test seals.' }
$steps += @{ Name = 'T21 Check the test site is clean r10'; Title = 'Check that the last round left nothing on the test site'; Dir = 'T21'; File = '90161Z-T21-probe-r10.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 20; Args = '-Part Clean -Label first'; Note = 'Signs in (CAC). Removes a test list, library or Visitors member left by the last round. If an earlier round left a test person in PFM Office, this step reports FAILED and the last step removes them.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 120; DoneText = ''; DoneLog = ''; Makes = @(); After = @(); Optional = $false; Help = 'Send the results as they are. Each removal runs even when an earlier one fails.'; Doing = 'Checking that the test site is clean.' }
$steps += @{ Name = 'T21 Make the probe list r10'; Title = 'Make the test list and library'; Dir = 'T21'; File = '90161Z-T21-probe-r10.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 20; Args = '-Part Make'; Note = 'Signs in (CAC). Makes the fake probe list (Visitors get Contribute on this list only) and library, uploads one fake workbook and writes the test page.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 120; DoneText = ''; DoneLog = ''; Makes = @(); After = @(); Optional = $false; Help = 'Send the results as they are. A second run changes nothing.'; Doing = 'Making the test list and library.' }
$steps += @{ Name = 'T20 Give Visitors Contribute on the intake lists r4'; Title = 'Check the lists and their access'; Dir = 'T20'; File = '90161Z-T20-provision-lists-r4.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'Signs in (CAC). Checks the 12 app lists and the PFM Office level, then gives the site Visitors Contribute on the 3 lists people write to. The site stays Read.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 240; DoneText = ''; DoneLog = ''; Makes = @(); After = @(); Optional = $false; Help = 'Send the results as they are. A second run changes nothing.'; Doing = 'Giving Visitors Contribute on the 3 intake lists.' }
$steps += @{ Name = 'T19 Add Closed Date and Waiver Warning r6'; Title = 'Add the column Closed Date and the warning type'; Dir = 'T19'; File = '90161Z-T19-list-update-r6.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 20; Args = ''; Note = 'Signs in (CAC). Adds the column Closed Date to the publications list and the type Waiver Warning to the activity log. Only adds; a column or value that is there stays and is reported.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 120; DoneText = ''; DoneLog = ''; Makes = @(); After = @(); Optional = $false; Help = 'Send the results as they are. A second run changes nothing.'; Doing = 'Adding the column Closed Date and the type Waiver Warning.' }
$steps += @{ Name = 'T21 Add the second person r10'; Title = 'Add the second person to the test site'; Dir = 'T21'; File = '90161Z-T21-probe-r10.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 20; Args = '-Part Person'; Note = 'A small window asks for the e-mail address of the second person. It stays on this computer. Adds that person to the site''s Visitors group.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 120; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T21 Make the probe list r10'); Optional = $false; Help = 'Send the results as they are. The address is never written to a file; the results show only yes or no.'; Doing = 'Adding the second person to the Visitors group.' }
$steps += @{ Name = 'T21 Ask for a new row r10'; Title = 'Copy the link of the new row form'; Dir = 'T21'; File = '90161Z-T21-probe-r10.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 5; Args = '-Part Ask'; Note = 'Notes on this computer that this round asks the second person for a new row, and puts the link of the new row form on the clipboard. No sign-in.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 60; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T21 Add the second person r10'); Optional = $false; Help = 'Send the results as they are.'; Doing = 'Copying the link of the new row form.' }
$steps += @{ Name = 'T21 Second person adds a row r10'; Title = 'Ask the second person to add one row'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You need one person of your office for about 5 minutes. They open the new row form, type the title you send them and select Save.'; Kind = 'guide'; Guide = @('1. Ask the second person to stay at a computer for about 5 minutes.', '2. Open Teams.', '3. Select "Chat".', '4. Select "New chat".', '5. In the box "To", type the e-mail address you gave RADE for the second person.', '6. Select the chat box.', '7. Press Ctrl+V (the link of the new row form is on the clipboard).', '8. In the chat box, type: Open this link, type T4a as the Title, select Save, tell me if it saved.', '9. Press Enter.', '10. Wait for the reply: the row saved, or no permission.', 'If nobody can help now: select "Skip" (the test of a new row then stays open).'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-t4a-asked.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: the second person tried a new row.'; Makes = @(); After = @('T21 Ask for a new row r10'); Optional = $false; Help = ''; Hide = @('failed'); Answers = @(@{ Key = 't4a-row'; Prompt = 'What did the second person see?'; Kind = 'pick'; Choices = @('The row was saved', 'No permission', 'The link did not open', 'Something else') }) }
$steps += @{ Name = 'T21 Open the test page r10'; Title = 'Open the test page'; Dir = 'T21'; File = '90161Z-T21-probe-r10.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 5; Args = '-Part Open'; Note = 'Opens the test page in your browser (no sign-in). Keep its tab open: the next steps use it.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 60; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T21 Make the probe list r10'); Optional = $false; Help = 'Send the results as they are.'; Doing = 'Opening the test page.' }
$steps += @{ Name = 'T24 Write the list IDs into the import file r7'; Title = 'Prepare the import file for your site'; Dir = 'T24'; File = '90161Z-T24-full-solution-test-r7.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 10; Args = '-Part 0'; Note = 'Signs in (CAC). Reads the ID of each app list the flows use, writes them into a copy of the import file, and puts the path of that copy on the clipboard. Changes nothing on the site. About 1 minute.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 60; DoneText = ''; DoneLog = ''; Makes = @(); After = @(); Optional = $false; Help = 'Send the results as they are. The step can be run again.'; Doing = 'Writing the list IDs into the import file.' }
$steps += @{ Name = 'T24 Import the full solution r7: choose the file'; Title = 'Start the import of the full flows'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You start the import of the full 90-161.Z flows (every flow On), with the file the last step prepared. The next step finishes it. About 4 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. If Power Automate asks you to sign in: sign in with your CAC.', '3. On the left, select "Solutions" (it can be under "More").', '4. Select "Import solution".', '5. Select "Browse".', '6. Select the box "File name".', '7. In the box "File name", press Ctrl+V (the path of the prepared file is on the clipboard).', '8. Select "Open".', '9. Select "Next".', 'If the Open window closes before the file is chosen: select "Browse" again.', 'If the box "File name" is empty after Ctrl+V: press Ctrl+V again.', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If the page refuses the file: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T24-file-chosen.txt'; Estimate = 240; DoneText = ''; DoneLog = 'Confirmed by you: chose the file.'; Makes = @(); After = @('T24 Write the list IDs into the import file r7', 'T21 Make the probe list r10'); Optional = $false; Help = ''; Hide = @('skip') }
$steps += @{ Name = 'T24 Import the full solution r7: finish'; Title = 'Finish the import of the full flows'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You finish the import of the full flows. It upgrades the flows of the last rounds, so a message or a banner that they were replaced is normal. About 5 minutes.'; Kind = 'guide'; Guide = @('1. If the page says the solution already exists: select "Upgrade".', '2. On the page "Connection References", select the arrow on the right of the first connection box.', '3. Select your connection in the list.', '4. In each other connection box on that page, select your connection too.', '5. Select "Next".', '6. If the box "1 Site URL" is empty: type the address you typed in the RADE box "Site address".', '7. If the box "2 Alert e-mail" is empty: type your work e-mail address (the one you use in Outlook).', '8. Select "Import".', '9. Wait for the line "Successfully imported".', 'If you see "The original workflow definition has been deactivated and replaced": go on.', 'If that message shows a button: select the button "Done" on that message.', 'If "Import" stays gray: in each box that already shows text, press Ctrl+A, Ctrl+X, then Ctrl+V.', 'If a connection box has no connection: select "New connection" in that box.', 'If you selected "New connection": select "Create".', 'If a connection box has a "Refresh" button: select it.', 'If a sign-in window opens: sign in with your CAC.', 'If the import fails: select "Download log file".', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If the log file is saved: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = ''; UrlConfig = ''; Marker = '90161Z-T24-imported.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: imported the full solution.'; Makes = @(); After = @('T24 Import the full solution r7: choose the file'); Optional = $false; Help = ''; Hide = @('skip'); Answers = @(@{ Key = 'import-conn'; Prompt = 'On the page "Connection References", what did you do?'; Kind = 'pick'; Choices = @('Connections were already chosen', 'I chose my connection in each box', 'I made a new connection', 'Something else') }, @{ Key = 'import-boxes'; Prompt = 'Which of the boxes "1 Site URL" and "2 Alert e-mail" did you type into before Import?'; Kind = 'pick'; Choices = @('Both', 'Only the site address', 'Only the e-mail', 'Neither') }, @{ Key = 'import-other'; Prompt = 'Did you type or change any other box before Import?'; Kind = 'pick'; Choices = @('No other box', 'Another box') }, @{ Key = 'import-replaced'; Prompt = 'Did a page or a banner say that the original workflow definition was deactivated and replaced?'; Kind = 'pick'; Choices = @('Yes', 'No', 'I did not see') }) }
$steps += @{ Name = 'T17 Import log reader r3'; Title = 'Read the import log if an import failed'; Dir = 'T17'; File = '90161Z-T17-import-log-r3.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 5; Args = ''; Note = 'Runs only if an import failed: copies the error rows of an import log saved in the last 3 hours, addresses masked. Otherwise it reports SKIPPED.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 60; DoneText = ''; DoneLog = ''; Makes = @(); After = @(); Optional = $false; Help = ''; Doing = 'Looking for an import log.' }
$steps += @{ Name = 'T24 Turn on all 10 flows r7'; Title = 'Turn on all 10 flows'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You check that all 10 flows read On and turn on any that do not: the 8 flows of the app and 2 test flows. About 3 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. On the left, select "Solutions" (it can be under "More").', '3. Select the solution "90-161.Z flows".', '4. Look at the column "Status" of each of the 10 flows.', '5. Remember each flow that reads Off (a question follows).', '6. If a flow reads Off: select the first one.', '7. If you selected a flow: select "Turn on".', '8. For each other flow that reads Off: select that flow and "Turn on".', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If a flow will not turn on: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T24-flows-on.txt'; Estimate = 180; DoneText = ''; DoneLog = 'Confirmed by you: all 10 flows On.'; Makes = @(); After = @('T24 Import the full solution r7: finish'); Optional = $false; Help = ''; Hide = @('skip'); Answers = @(@{ Key = 'off-before'; Prompt = 'Which flows read Off before you turned them on? Type their codes, for example F03, or type: none'; Kind = 'text'; Choices = @() }) }
