$steps += @{ Name = 'T21 Use the list button r10'; Title = 'Use the button in the list'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You select a button in a list view that starts a test flow for that row. About 4 minutes.'; Kind = 'guide'; Guide = @('1. In the browser, select the tab "90-161.Z test page".', '2. Select "Open the list with the button".', '3. If the top right of the list shows "All Items": select "All Items" to open the menu of views.', '4. If a menu of views opened: select "ProbeButton".', '5. Look at the first row for a button "Run the test flow".', '6. In the first row, select "Run the test flow".', '7. Look at the panel that opened for a button "Run".', '8. Select "Run".', '9. If the panel asks you to continue or to allow a connection: select "Continue".', '10. Wait until the panel says the flow ran, or shows an error.', 'If you see an error: wait 5 minutes, reload the list page, and try 1 more time.'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-button-used.txt'; Estimate = 240; DoneText = 'I tried the button'; DoneLog = 'Confirmed by you: used the button.'; Makes = @(); After = @('T21 Make the list view with the flow button r10'); Optional = $false; Help = ''; Hide = @('failed', 'skip'); Answers = @(@{ Key = 'btn-view'; Prompt = 'Which view did the link open first?'; Kind = 'pick'; Choices = @('ProbeButton', 'All Items', 'Another view') }, @{ Key = 'btn-show'; Prompt = 'What did the ProbeButton view show in each row?'; Kind = 'pick'; Choices = @('A button Run the test flow', 'No button', 'The plain list') }, @{ Key = 'btn-panel'; Prompt = 'What did the panel say after you selected Run?'; Kind = 'pick'; Choices = @('The flow ran', 'The flow was not found', 'An error', 'No panel opened') }) }
$steps += @{ Name = 'T24 Full solution test, part 1 r7'; Title = 'Prepare the full flow test'; Dir = 'T24'; File = '90161Z-T24-full-solution-test-r7.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 75; Args = '-Part 1'; Note = 'Signs in (CAC). Writes the settings rows (Test mode Yes) and fake rows, then waits twice 16 minutes for the flows that check every 15 minutes. About 40 minutes.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 2400; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T24 Turn on all 10 flows r7'); Optional = $false; Help = 'Send the results as they are. A FAIL here is a finding about a flow.'; Doing = 'Running the first part of the flow test (about 40 minutes).' }
$steps += @{ Name = 'T24 Run F02 once and F04 once r7'; Title = 'Run two of the flows by hand'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You run the review flow and the status report flow by hand. The status report sends one test e-mail to you. About 5 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. On the left, select "Solutions" (it can be under "More").', '3. Select the solution "90-161.Z flows".', '4. Select the flow "90161Z F02 Next Review Due r3".', '5. Select "Run" at the top.', '6. Select the Back arrow at the top left to return to the solution.', '7. Select the flow "90161Z F04 Status Report r4".', '8. Select "Run" at the top.', '9. In the box "Send the report to (e-mail)", type your work e-mail address (the one in Outlook).', '10. Select "Run flow".', 'If a panel asks you to continue: select "Continue".', 'After the second run, wait 2 minutes.', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If "Run" is missing or a run fails: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T24-ran-f02-f04.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: ran F02 and F04.'; Makes = @(); After = @('T24 Full solution test, part 1 r7'); Optional = $false; Help = ''; Hide = @('skip') }
$steps += @{ Name = 'T24 Full solution test, part 2 r7'; Title = 'Check what the two flows did'; Dir = 'T24'; File = '90161Z-T24-full-solution-test-r7.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = '-Part 2'; Note = 'Signs in (CAC). Checks what the two flows did: review dates, review rows, the status-report log row and its count of open actions (rows with no Closed Date). About 4 minutes.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 240; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T24 Run F02 once and F04 once r7'); Optional = $false; Help = 'Send the results as they are. A FAIL here is a finding about a flow.'; Doing = 'Running the second part of the flow test.' }
$steps += @{ Name = 'T24 Find the F04 e-mail r7'; Title = 'Find the test e-mail of the status report'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You look for the test e-mail of the status report and answer 3 questions. About 3 minutes.'; Kind = 'guide'; Guide = @('1. Open Outlook (on this computer or in the browser).', '2. Select "Inbox".', '3. Look for an e-mail whose subject starts with "TEST MODE" (question 1).', '4. If it is not in the Inbox: open the folder "Junk Email".', '5. Open that e-mail.', '6. Look at its tables: each starts with the word "Step" and a number (question 2).', '7. Look at the To line (question 3).'); Url = ''; UrlConfig = ''; Marker = '90161Z-T24-email-looked.txt'; Estimate = 180; DoneText = 'I looked'; DoneLog = 'Confirmed by you: looked at the F04 e-mail.'; Makes = @(); After = @('T24 Full solution test, part 2 r7'); Optional = $false; Help = ''; Hide = @('failed', 'skip'); Answers = @(@{ Key = 'f04-found'; Prompt = 'Where is the F04 e-mail whose subject starts with TEST MODE?'; Kind = 'pick'; Choices = @('Inbox', 'Junk Email', 'Not found') }, @{ Key = 'f04-tables'; Prompt = 'Does it show 2 or more tables, each headed Step and a number?'; Kind = 'pick'; Choices = @('Yes', 'No'); ShowKey = 'f04-found'; ShowIn = @('Inbox', 'Junk Email') }, @{ Key = 'f04-to'; Prompt = 'Is the To line your own work e-mail address?'; Kind = 'pick'; Choices = @('Yes', 'No'); ShowKey = 'f04-found'; ShowIn = @('Inbox', 'Junk Email') }) }
$steps += @{ Name = 'T24 Run F02 again r7'; Title = 'Run the review flow a second time'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You run the review flow a second time, so the next step can check that it made no second review row. About 2 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. On the left, select "Solutions" (it can be under "More").', '3. Select the solution "90-161.Z flows".', '4. Select the flow "90161Z F02 Next Review Due r3".', '5. Select "Run" at the top.', '6. If a panel asks you to continue: select "Continue".', '7. Wait until the run shows "Succeeded" or "Failed".', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If the run shows "Failed": select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T24-f02-again.txt'; Estimate = 120; DoneText = ''; DoneLog = 'Confirmed by you: ran F02 again.'; Makes = @(); After = @('T24 Find the F04 e-mail r7'); Optional = $false; Help = ''; Hide = @('skip') }
$steps += @{ Name = 'T24 Full solution test, part 3 r7'; Title = 'Check that the second run added no row'; Dir = 'T24'; File = '90161Z-T24-full-solution-test-r7.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 20; Args = '-Part 3'; Note = 'Signs in (CAC). Checks that the second run of the review flow made no second review row. Nothing is removed here. About 2 minutes.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 120; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T24 Run F02 again r7'); Optional = $false; Help = 'Send the results as they are. A FAIL here is a finding about a flow.'; Doing = 'Running the third part of the flow test.' }
$steps += @{ Name = 'T24 Find the F08 e-mail r7'; Title = 'Find the waiver warning e-mail'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You look for the test e-mail that warns about a fake waiver whose approver leads an office, and answer 2 questions. About 3 minutes.'; Kind = 'guide'; Guide = @('1. Open Outlook (on this computer or in the browser).', '2. Select "Inbox".', '3. Look for e-mails whose subject starts with "90-161.Z waiver tier warning" (question 1).', '4. If none is in the Inbox: open the folder "Junk Email".', '5. Open the newest of those e-mails.', '6. Look for the words "T-1" and "Table A10.1" in it (question 2).'); Url = ''; UrlConfig = ''; Marker = '90161Z-T24-f08-looked.txt'; Estimate = 180; DoneText = 'I looked'; DoneLog = 'Confirmed by you: looked for the F08 e-mail.'; Makes = @(); After = @('T24 Full solution test, part 3 r7'); Optional = $false; Help = ''; Hide = @('failed', 'skip'); Answers = @(@{ Key = 'f08-hand'; Prompt = 'How many e-mails with the subject 90-161.Z waiver tier warning did you find?'; Kind = 'pick'; Choices = @('Exactly 1 in the Inbox', '1 in Junk Email', '2 or more', 'None') }, @{ Key = 'f08-text'; Prompt = 'Does it name the tier T-1 and Table A10.1?'; Kind = 'pick'; Choices = @('Yes', 'No'); ShowKey = 'f08-hand'; ShowIn = @('Exactly 1 in the Inbox', '1 in Junk Email', '2 or more') }) }
$steps += @{ Name = 'T21 Read the test results r10'; Title = 'Read the health, person and button results'; Dir = 'T21'; File = '90161Z-T21-probe-r10.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 20; Args = '-Part Read'; Note = 'Signs in (CAC). Reads counts only: the health flow row, the rows by the second person and the rows of the button flow. Waits up to about 4 minutes for the health row.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 180; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T21 Make the probe list r10'); Optional = $false; Help = 'Send the results as they are.'; Doing = 'Reading what the flows wrote.' }
