        P = @($(if ($nr) { 'A newer round, ' + $nr + ', is in the repository. Close this window and run ' + $nr + ' instead.' } else { '' })); Options = $list; OnOption = { param($j) & $ui.Pick $j }
        PageLink = [bool](@($ui.Newer.Values | Where-Object { $_ }).Count)
