          $(if ($ui.TourI) { @{ Text = 'Back'; Act = { & $ui.VTour ($ui.TourI - 1) } } } else { $null }), $(if ($last) { $null } else { @{ Text = 'Skip the tour'; Act = { & $ui.EndTour } } })) } }
